parameters.jsCode:
const response = $input.first().json;
let content = '';
if (response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
  content = response.candidates[0].content.parts[0].text;
} else if (response.choices && response.choices[0]?.message?.content) {
  content = response.choices[0].message.content;
}

// Bersihkan markdown json jika ada
const cleaned = content.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    judul: 'Cara Deteksi Fraud Karyawan dalam 3 Menit',
    hook: 'Pernah curiga stok barang sering minus tapi laporan kasir selalu pas?',
    visual_prompt: 'Cinematic corporate audit office, high contrast dramatic lighting, business auditor reviewing anomaly detection graph on modern accounting ERP dashboard, ultra realistic 8k, camera zoom in',
    voiceover: 'Jangan biarkan kebocoran kas merugikan bisnis Anda. Terapkan 3 langkah audit kilat: periksa void kasir, cocokkan mutasi bank otomatis, dan kunci akses otorisasi ganda.',
    caption_ig: 'Bisnis sering bocor bukan karena omset sepi, tapi sistem kontrolnya longgar! Simak 3 langkah audit kilat untuk amankan profit Anda. Komen MAU untuk panduan lengkapnya! #tipsbisnis #auditkeuangan #seventhsoft'
  };
}

return {
  json: {
    chat_id: $('Telegram Trigger (Perintah Video)').first().json.message.chat.id,
    judul: parsed.judul,
    hook: parsed.hook,
    visual_prompt: parsed.visual_prompt,
    voiceover: parsed.voiceover,
    caption_ig: parsed.caption_ig
  }
};
